interface Staged { readonly index: Index; parts(): AsyncIterable<Chunk>; }
async function consume(s: Staged, sink: Sink): Promise<void> {
  for (const wanted of s.index.wanted) {      // stage 1 metadata decides the work
    for await (const chunk of s.parts()) {    // stage 2: pulled on demand
      await sink.write(chunk);                // early return cancels via return()
    }
  }
}
